"string"}},"required":["id","scene","account","direction","parts","change","amount","balance","event_id","source_quote"],"additionalProperties":false}},"events":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string"},"scene":{"type":"integer"},"after":{"type":"array","items":{"type":"string"}},"description":{"type":"string"},"source_quote":{"type":"string"}},"required":["id","scene","after","description","source_quote"],"additionalProperties":false}},"resource_ledgers":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string"},"units":{"type":"object","additionalProperties":{"type":"integer","minimum":1}},"unit_equations":{"type":"array","items":{"type":"object","properties":{"left":{"type":"string"},"right":{"type":"string"},"source_quote":{"type":"string"}},"required":["left","right","source_quote"],"additionalProperties":false}},"accounts":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string"},"opening":{"type":"integer"},"opening_quote":{"type":"string"}},"required":["id","opening","opening_quote"],"additionalProperties":false}},"transfers":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string"},"scene":{"type":"integer"},"account":{"type":"string"},"direction":{"type":"string"},"parts":{"type":"string"},"change":{"type":"string"},"amount":{"type":"integer"},"balance":{"type":"integer"},"event_id":{"type":"string"},"source_quote":{"type":"string"}},"required":["id","scene","account","direction","parts","change","amount","balance","event_id","source_quote"],"additionalProperties":false}}},"required":["id","units","unit_equations","accounts","transfers"],"additionalProperties":false}}},"required":["schema","focus","facts","units","unit_equations","accounts","transfers","events","resource_ledgers"],"additionalProperties":false}}}
